src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <float.h>

template <typename scalar_t>
__global__ void max_reduce_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int dim0,
    const int dim1,
    const int dim2,
    const int reduce_dim,
    const int out_numel)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= out_numel) return;

    float max_val = -FLT_MAX;

    if (reduce_dim == 0) {                     // reduce over dim0 (batch)
        int i = idx / dim2;                    // dim1 index
        int j = idx % dim2;                    // dim2 index
        for (int b = 0; b < dim0; ++b) {
            int offset = b * dim1 * dim2 + i * dim2 + j;
            float v = __half2float(input[offset]);
            max_val = fmaxf(max_val, v);
        }
        output[idx] = __float2half(max_val);
    }
    else if (reduce_dim == 1) {                // reduce over dim1
        int b = idx / dim2;                    // dim0 index
        int j = idx % dim2;                    // dim2 index
        for (int i = 0; i < dim1; ++i) {
            int offset = b * dim1 * dim2 + i * dim2 + j;
            float v = __half2float(input[offset]);
            max_val = fmaxf(max_val, v);
        }
        output[idx] = __float2half(max_val);
    }
    else {                                     // reduce over dim2
        int b = idx / dim1;                    // dim0 index
        int i = idx % dim1;                    // dim1 index
        for (int j = 0; j < dim2; ++j) {
            int offset = b * dim1 * dim2 + i * dim2 + j;
            float v = __half2float(input[offset]);
            max_val = fmaxf(max_val, v);
        }
        output[idx] = __float2half(max_val);
    }
}

// ------------------------------------------------------------------
// C++ interface
// ------------------------------------------------------------------
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t reduce_dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(reduce_dim >=0 && reduce_dim <=2, "reduce_dim must be 0,1 or 2");

    auto sizes = input.sizes();
    int64_t dim0 = sizes[0];
    int64_t dim1 = sizes[1];
    int64_t dim2 = sizes[2];

    torch::Tensor output;
    if (reduce_dim == 0) {
        output = torch::empty({dim1, dim2}, input.options());
    } else if (reduce_dim == 1) {
        output = torch::empty({dim0, dim2}, input.options());
    } else {
        output = torch::empty({dim0, dim1}, input.options());
    }

    const int threads = 256;
    int64_t out_numel = output.numel();
    const int blocks = (out_numel + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "max_reduce_cuda", ([&] {
        max_reduce_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            dim0, dim1, dim2,
            static_cast<int>(reduce_dim),
            static_cast<int>(out_numel));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("max_reduce_cuda", &max_reduce_cuda, "Max reduction over a dimension (CUDA, fp16)");
}
'''

# Compile the extension
ext = load_inline(name='max_reduce_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['max_reduce_cuda'],
                  verbose=False)

# ------------------------------------------------------------------
# Python wrapper module
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.half()
        return ext.max_reduce_cuda(x, self.dim)

# ------------------------------------------------------------------
# Helper functions matching the reference API (optional)
# ------------------------------------------------------------------
def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [1]  # default reduction dimension
